def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = tuple(h[1] for h in history)
    my = tuple(h[0] for h in history)
    last_me, last_opp = history[-1]

    opp_d = sum(1 for x in opp if x == 'D')
    opp_c = n - opp_d
    my_c = sum(1 for x in my if x == 'C')

    d8 = sum(1 for x in opp[-8:] if x == 'D')
    d12 = sum(1 for x in opp[-12:] if x == 'D')

    after_my_c_d = 0
    after_my_d_c = 0
    after_my_d_d = 0

    for i in range(n - 1):
        if my[i] == 'C':
            if opp[i + 1] == 'D':
                after_my_c_d += 1
        else:
            if opp[i + 1] == 'C':
                after_my_d_c += 1
            else:
                after_my_d_d += 1

    exploitative = (
        after_my_c_d >= 3
        and my_c >= 10
        and after_my_c_d * 5 >= my_c * 2
    )

    if (
        (n >= 12 and d12 >= 7)
        or (n >= 15 and opp_d * 4 >= n * 3)
        or exploitative
    ):
        if last_opp == 'C' and d8 <= 2 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if (
            d8 >= 3
            or d12 >= 4
            or exploitative
            or (n >= 10 and opp_d * 20 >= n * 13)
        ):
            if last_me == 'D' and opp_c * 3 >= n * 2 and d12 <= 4:
                return 'C' if rng.random() < 0.5 else 'D'
            return 'D'

        if opp_c * 3 >= n * 2:
            if last_me == 'D':
                return 'C' if rng.random() < 0.65 else 'D'
            return 'D' if rng.random() < 0.55 else 'C'

        return 'D'

    if d8 >= 3 or (n >= 15 and opp_d * 2 >= n) or exploitative:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if (
        opp_c * 10 >= n * 8
        and after_my_d_c >= 1
        and after_my_d_c > after_my_d_d
        and d12 <= 3
    ):
        if rng.random() < (0.6 if n >= 60 else 0.12):
            return 'D'

    if (
        last_me == 'C'
        and last_opp == 'C'
        and after_my_d_c >= 1
        and after_my_d_c > after_my_d_d
        and opp_c * 10 >= n * 8
    ):
        if rng.random() < 0.2:
            return 'D'

    if opp_c == n:
        if n == 80 and rng.random() < 0.25:
            return 'D'
        if n >= 90 and rng.random() < 0.1:
            return 'D'

    return 'C'
